// Import of required libraries
import { test, expect, SkyrampClient, getValue, getResponseValue } from '@skyramp/skyramp';
import { createOwner, getOwner, deleteOwner } from './skyrampUtils';

// Owner city at exactly the new upper bound (120 chars) and one past it (121 chars).
const CITY_AT_MAX = "Skyramp Boundary City xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx";
const CITY_OVER_MAX = "Skyramp Boundary City xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx";

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();

    const ownersPostResponse = await createOwner(client);

    expect(ownersPostResponse.statusCode, 'status code').toBe(201);
    expect(getResponseValue(ownersPostResponse, "city"), 'city').toBe(CITY_AT_MAX);
    expect(String(getResponseValue(ownersPostResponse, "city")).length, 'city length').toBe(120);
    expect(getResponseValue(ownersPostResponse, "firstName"), 'firstName').toBe("Cityboundary");
    expect(getResponseValue(ownersPostResponse, "lastName"), 'lastName').toBe("Maxlen");
    expect(getResponseValue(ownersPostResponse, "address"), 'address').toBe("1 Boundary St");
    expect(getResponseValue(ownersPostResponse, "telephone"), 'telephone').toBe("6085550120");
    expect(Number(getResponseValue(ownersPostResponse, "id")), 'id').toBeGreaterThan(0);
    expect(getValue(ownersPostResponse, "pets.0"), 'first pet').toBeNull();

    const ownersOwnersGetResponse = await getOwner(client, getResponseValue(ownersPostResponse, "id"));

    expect(ownersOwnersGetResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(ownersOwnersGetResponse, "id"), 'id').toBe(getResponseValue(ownersPostResponse, "id"));
    expect(getResponseValue(ownersOwnersGetResponse, "city"), 'city').toBe(CITY_AT_MAX);
    expect(String(getResponseValue(ownersOwnersGetResponse, "city")).length, 'persisted city length').toBe(120);
    expect(getResponseValue(ownersOwnersGetResponse, "lastName"), 'lastName').toBe("Maxlen");
    expect(getResponseValue(ownersOwnersGetResponse, "telephone"), 'telephone').toBe("6085550120");

    const ownersPost1Response = await createOwner(client, CITY_OVER_MAX, "Toolong", "6085550121", 400);

    expect(ownersPost1Response.statusCode, 'status code').toBe(400);
    expect(getValue(ownersPost1Response, "schemaValidationErrors.0.field"), 'rejected field').toBe("city");
    expect(getValue(ownersPost1Response, "schemaValidationErrors.0.defaultMessage"), 'rejection message').toBe("size must be between 1 and 120");
    expect(getValue(ownersPost1Response, "schemaValidationErrors.0.rejectedValue"), 'rejected value').toBe(CITY_OVER_MAX);
    expect(getValue(ownersPost1Response, "schemaValidationErrors.1"), 'second validation error').toBeNull();

    const ownersPost2Response = await createOwner(client, "", "Emptycity", "6085550122", 400);

    expect(ownersPost2Response.statusCode, 'status code').toBe(400);
    expect(getValue(ownersPost2Response, "schemaValidationErrors.0.field"), 'rejected field').toBe("city");
    expect(getValue(ownersPost2Response, "schemaValidationErrors.0.defaultMessage"), 'rejection message').toBe("size must be between 1 and 120");
    expect(getValue(ownersPost2Response, "schemaValidationErrors.0.rejectedValue"), 'rejected value').toBe("");
    expect(getValue(ownersPost2Response, "schemaValidationErrors.1"), 'second validation error').toBeNull();

    const ownersOwnersDeleteResponse = await deleteOwner(client, getResponseValue(ownersPostResponse, "id"));

    expect(ownersOwnersDeleteResponse.statusCode, 'status code').toBe(204);
});
